PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from unittest.mock import patch
from urllib.error import HTTPError, URLError
import openai_client

class FailingOpener:
    def __init__(self, error):
        self.error = error

    def open(self, request, timeout):
        raise self.error

with patch.dict('os.environ', {'OPENAI_API_KEY': 'fake-key'}):
    for error in (HTTPError('https://api.openai.com/v1/responses', 400, 'secret', {}, None), URLError('secret')):
        with patch.object(openai_client.urllib.request, 'build_opener', return_value=FailingOpener(error)):
            try:
                openai_client.send_prompt('secret')
            except openai_client.OpenAIClientError as exc:
                assert 'secret' not in str(exc)
            else:
                raise AssertionError('expected sanitized API error')
print('error sanitization passed')
